"""Checks that cases.json (generated by make_cases.py) matches what imzo_ref actually does.

The file may carry extra top-level keys added by later tasks; only cbor/requests/frames are checked here.
Run: python -m unittest test_cases -v
"""

import json
import unittest
from pathlib import Path

import imzo_ref as imzo
from imzo_ref import ProtocolError

CASES_PATH = Path(__file__).with_name("cases.json")

REQUIRED = {
    "cbor": {
        "non-canonical int",
        "indefinite-length array",
        "duplicate map key",
        "trailing byte",
        "nesting depth 5",
        "invalid utf-8",
        "map with integer key",
        "16385-byte string",
    },
    "requests": {
        "valid 12-person payroll",
        "valid 50-item",
        "51 items",
        "total off by one",
        "account of 15 digits",
        "account of 20 digits with a letter",
        "amount 0",
        "amount 2**53+1",
        "name in NFD form",
        "name containing U+202E",
        "name containing unassigned U+0378",
        "name of exactly 64 bytes",
        "name of 65 bytes",
        "ap [2, 1]",
        "unknown op",
        "extra field",
    },
    "frames": {
        "valid 5-frame request",
        "shuffled with repeats",
        "flipped base64 character",
        "missing frame",
        "two sessions mixed",
        "index 257 of 257",
    },
}


def error_code(fn, *args):
    try:
        return fn(*args), None
    except ProtocolError as exc:
        return None, exc.code


class TestCases(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.cases = json.loads(CASES_PATH.read_text())

    def test_required_cases_exist(self):
        for section, names in REQUIRED.items():
            have = {c["name"] for c in self.cases[section]}
            with self.subTest(section):
                self.assertEqual(sorted(names - have), [])

    def test_names_are_unique(self):
        for section in REQUIRED:
            names = [c["name"] for c in self.cases[section]]
            with self.subTest(section):
                self.assertEqual(len(names), len(set(names)))

    def test_hex_is_lowercase(self):
        for section in ("cbor", "requests"):
            for case in self.cases[section]:
                with self.subTest(case["name"]):
                    self.assertEqual(case["hex"], case["hex"].lower())
                    bytes.fromhex(case["hex"])

    def test_cbor_cases_match_reference(self):
        for case in self.cases["cbor"]:
            with self.subTest(case["name"]):
                data = bytes.fromhex(case["hex"])
                value, code = error_code(imzo.loads, data)
                if case["ok"]:
                    self.assertIsNone(code)
                    self.assertNotIn("error", case)
                    self.assertEqual(imzo.dumps(value).hex(), case["hex"])
                else:
                    self.assertEqual(code, case["error"])

    def test_request_cases_match_reference(self):
        for case in self.cases["requests"]:
            with self.subTest(case["name"]):
                data = bytes.fromhex(case["hex"])
                req, code = error_code(imzo.parse_request, data)
                if "error" in case:
                    self.assertEqual(code, case["error"])
                    for key in ("total", "count", "fingerprint"):
                        self.assertNotIn(key, case)
                else:
                    self.assertIsNone(code)
                    self.assertEqual(case["total"], sum(i[2] for i in req["items"]))
                    self.assertEqual(case["count"], len(req["items"]))
                    self.assertEqual(case["fingerprint"], imzo.fingerprint(data))

    def test_frame_cases_match_reference(self):
        for case in self.cases["frames"]:
            with self.subTest(case["name"]):
                result, code = error_code(imzo.frames_decode, case["frames"])
                if "error" in case:
                    self.assertEqual(code, case["error"])
                    self.assertNotIn("kind", case)
                    self.assertNotIn("body_hex", case)
                else:
                    self.assertIsNone(code)
                    kind, body = result
                    self.assertEqual(case["kind"], kind)
                    self.assertEqual(case["body_hex"], body.hex())

    def test_expected_outcomes_of_named_cases(self):
        by_name = {s: {c["name"]: c for c in self.cases[s]} for s in REQUIRED}
        self.assertEqual(by_name["requests"]["total off by one"]["error"], "TOTAL MISMATCH")
        self.assertEqual(by_name["requests"]["valid 12-person payroll"]["count"], 12)
        self.assertEqual(by_name["requests"]["valid 50-item"]["count"], 50)
        self.assertEqual(by_name["requests"]["51 items"]["error"], "BAD FORMAT")
        self.assertEqual(by_name["requests"]["name of exactly 64 bytes"]["count"], 1)
        self.assertEqual(by_name["requests"]["name of 65 bytes"]["error"], "BAD FORMAT")
        self.assertEqual(by_name["frames"]["flipped base64 character"]["error"], "CRC")
        self.assertEqual(by_name["frames"]["missing frame"]["error"], "INCOMPLETE")
        self.assertEqual(by_name["frames"]["two sessions mixed"]["error"], "BAD FORMAT")
        self.assertEqual(by_name["frames"]["index 257 of 257"]["error"], "BAD FORMAT")
        self.assertEqual(len(by_name["frames"]["valid 5-frame request"]["frames"]), 5)
        self.assertEqual(by_name["frames"]["valid 5-frame request"]["kind"], "rq")
        self.assertTrue(by_name["cbor"]["16385-byte string"]["hex"].startswith("594001"))
        self.assertFalse(by_name["cbor"]["16385-byte string"]["ok"])

    def test_frame_valid_body_is_a_valid_request(self):
        case = next(c for c in self.cases["frames"] if c["name"] == "valid 5-frame request")
        imzo.parse_request(bytes.fromhex(case["body_hex"]))

    def test_generator_is_deterministic_and_in_sync(self):
        import make_cases

        first = make_cases.build_cases()
        self.assertEqual(first, make_cases.build_cases())
        for section in REQUIRED:
            self.assertEqual(first[section], self.cases[section])


if __name__ == "__main__":
    unittest.main()
